from pathlib import Path
import sys
p=Path(sys.argv[1]);p.parent.mkdir(parents=True,exist_ok=True)
with p.open('a',encoding='utf-8',newline='') as f:f.write("────────────────────────────────────────────────────\n \n-const TEST_HOME = join(tmpdir(), `arra-codex-plugin-${Date.now()}`);\n-const CODEX_DIR = join(TEST_HOME, \".codex\");\n-const CONFIG_PATH = join(CODEX_DIR, \"config.toml\");\n-const MARKETPLACE_DIR = join(\n-  TEST_HOME,\n-  \".codex\",\n-  \".tmp\",\n-  \"bundled-marketplaces\",\n-  \"arra-oracle-skills\"\n-);\n+let TEST_HOME: string;\n+let CODEX_DIR: string;\n+let CONFIG_PATH: string;\n+let MARKETPLACE_DIR: string;\n \n // Minimal mock skills for unit tests (no disk I/O needed for descriptor tests)\n-const MOCK_SKILLS: Skill[] = [\n+let MOCK_SKILLS: Skill[];\n+const makeMockSkills = (): Skill[] => [\n   {\n     name: \"rrr\",\n     description: \"Session retrospective with AI diary\",\n@@ -62,6 +57,11 @@ const MOCK_SKILLS: Skill[] = [\n // ── Setup / teardown ──────────────────────────────────────────────────────────\n \n beforeAll(async () => {\n+  TEST_HOME = await mkdtemp(join(tmpdir(), \"arra-codex-plugin-\"));\n+  CODEX_DIR = join(TEST_HOME, \".codex\");\n+  CONFIG_PATH = join(CODEX_DIR, \"config.toml\");\n+  MARKETPLACE_DIR = getCodexMarketplaceDir(TEST_HOME);\n+  MOCK_SKILLS = makeMockSkills();\n   await mkdir(CODEX_DIR, { recursive: true });\n   // Simulate Codex 0.128.0+ by creating a config.toml with existing marketplace entries\n   await writeFile(\n@@ -78,7 +78,7 @@ beforeAll(async () => {\n });\n \n afterAll(async () => {\n-  if (existsSync(TEST_HOME)) await rm(TEST_HOME, { recursive: true });\n+  if (TEST_HOME) await rm(TEST_HOME, { recursive: true, force: true });\n });\n \n // ── isCodexPluginMarketplace ──────────────────────────────────────────────────\n@@ -89,7 +89,7 @@ describe(\"isCodexPluginMarketplace\", () => {\n   });\n \n   it(\"returns false for a home dir without config.toml\", () => {\n-    expect(isCodexPluginMarketplace(join(tmpdir(), \"nonexistent-home-99999\"))).toBe(false);\n+    expect(isCodexPluginMarketplace(join(TEST_HOME, \"absent-home\"))).toBe(false);\n   });\n });\n \n@@ -201,10 +201,12 @@ describe(\"installCodexPluginMarketplace (V1 — Codex < 0.130)\", () => {\n // ── V2 format (Codex 0.130+) ──────────────────────────────────────────────────\n \n describe(\"installCodexPluginMarketplace (V2 — Codex 0.130+)\", () => {\n-  const V2_MARKETPLACE_DIR = join(TEST_HOME, \"v2-marketplace\");\n-  const V2_CONFIG_PATH = join(TEST_HOME, \"v2-config.toml\");\n+  let V2_MARKETPLACE_DIR: string;\n+  let V2_CONFIG_PATH: string;\n \n   beforeAll(async () => {\n+    V2_MARKETPLACE_DIR = join(TEST_HOME, \"v2-marketplace\");\n+    V2_CONFIG_PATH = join(TEST_HOME, \"v2-config.toml\");\n     await writeFile(V2_CONFIG_PATH, `[marketplaces.openai-bundled]\\nsource_type = \"bundled\"\\n`);\n     await installCodexPluginMarketplace(MOCK_SKILLS, \"26.5.0-v2\", \"no-shell\", {\n       marketplaceDir: V2_MARKETPLACE_DIR,\n@@ -292,10 +294,12 @@ describe(\"isCodexV2Format\", () => {\n // ── Integration: uses real skills ─────────────────────────────────────────────\n \n describe(\"installCodexPluginMarketplace (real skills)\", () => {\n-  const REAL_MARKETPLACE_DIR = join(TEST_HOME, \"real-marketplace\");\n-  const REAL_CONFIG_PATH = join(TEST_HOME, \"real-config.toml\");\n+  let REAL_MARKETPLACE_DIR: string;\n+  let REAL_CONFIG_PATH: string;\n \n   beforeAll(async () => {\n+    REAL_MARKETPLACE_DIR = join(TEST_HOME, \"real-marketplace\");\n+    REAL_CONFIG_PATH = join(TEST_HOME, \"real-config.toml\");\n     // Seed a minimal config.toml\n     await writeFile(\n       REAL_CONFIG_PATH,\n@@ -338,3 +342,39 @@ describe(\"installCodexPluginMarketplace (real skills)\", () => {\n     }\n   });\n });\n+\n+// ── Upgrading an existing marketplace ────────────────────────────────────────\n+\n+describe(\"Codex marketplace format migration\", () => {\n+  it(\"replaces legacy metadata and installs readable skill content on 0.130+\", async () => {\n+    const marketplaceDir = join(TEST_HOME, \"upgrade-marketplace\");\n+    const configPath = join(TEST_HOME, \"upgrade-config.toml\");\n+    const sourceDir = join(TEST_HOME, \"source-rrr\");\n+    await mkdir(sourceDir, { recursive: true });\n+    const body = \"---\\nname: rrr\\ndescription: Retrospective\\n---\\n# Retrospective\\n\";\n+    await writeFile(join(sourceDir, \"SKILL.md\"), body);\n+    const skills: Skill[] = [{ name: \"rrr\", description: \"Retrospective\", path: sourceDir }];\n+\n+    await installCodexPluginMarketplace(skills, \"26.5.14\", \"no-shell\", {\n+      marketplaceDir, configPath, codexVersion: \"0.128.0\",\n+    });\n+    expect(existsSync(join(marketplaceDir, \"manifest.toml\"))).toBe(true);\n+\n+    await installCodexPluginMarketplace(skills, \"26.5.14\", \"no-shell\", {\n+      marketplaceDir, configPath, codexVersion: \"0.130.0\",\n+    });\n+    const pluginDir = join(marketplaceDir, \"plugins\", \"rrr\");\n+    expect(existsSync(join(marketplaceDir, \"manifest.toml\"))).toBe(false);\n+    expect(existsSync(join(pluginDir, \"plugin.toml\"))).toBe(false);\n+    expect(existsSync(join(pluginDir, \"prompt.md\"))).toBe(false);\n+    expect(await readFile(join(pluginDir, \"skills\", \"rrr\", \"SKILL.md\"), \"utf-8\")).toBe(body);\n+    expect(JSON.parse(await readFile(join(pluginDir, \".codex-plugin\", \"plugin.json\"), \"utf-8\")).skills).toBe(\"./skills/\");\n+\n+    await installCodexPluginMarketplace(skills, \"26.5.14\", \"no-shell\", {\n+      marketplaceDir, configPath, codexVersion: \"0.128.0\",\n+    });\n+    expect(existsSync(join(pluginDir, \".codex-plugin\"))).toBe(false);\n+    expect(existsSync(join(pluginDir, \"skills\"))).toBe(false);\n+    expect(await readFile(join(pluginDir, \"prompt.md\"), \"utf-8\")).toBe(body);\n+  });\n+});\n")
